class TNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def tree_to_list(node):
    # Serialize a tree to a preorder list with None for missing children.
    if node is None:
        return [None]
    return [node.val] + tree_to_list(node.left) + tree_to_list(node.right)

def list_to_tree(lst):
    # Deserialize a preorder list back to a tree.
    it = iter(lst)
    def build():
        val = next(it, None)
        if val is None:
            return None
        node = TNode(val)
        node.left = build()
        node.right = build()
        return node
    return build()

