def stack_push(stack, value):
    return stack + [value]

def stack_pop(stack):
    if not stack:
        raise IndexError('empty stack')
    return stack[:-1], stack[-1]

def stack_peek(stack):
    if not stack:
        raise IndexError('empty stack')
    return stack[-1]

def stack_apply_top2(stack, func):
    s, b = stack_pop(stack)
    s, a = stack_pop(s)
    return stack_push(s, func(a, b))

