k = compose_checked(float_to_int, int_to_str)
assert k(3.7) == '3'

# int->str, float->int: str != float, should fail
try:
    compose_checked(int_to_str, float_to_int)
    assert False, 'Should have raised TypeError'
except TypeError:
    pass
